<?php
function main() {
    $line = trim(fgets(STDIN));
    list($a, $b, $p, $x) = array_map('intval', explode(' ', $line));

    $count = 0;

    // Iterate over all possible residues r (mod p-1)
    for ($r = 0; $r < $p - 1; $r++) {
        // Compute a^r mod p
        $ar = pow_mod($a, $r, $p);

        // Solve ar * n ≡ b (mod p) for n
        // ar * n ≡ b (mod p)
        // n ≡ b * inv(ar) (mod p)
        $inv_ar = mod_inverse($ar, $p);
        if ($inv_ar === null) {
            continue; // ar and p are not coprime, no solution
        }
        $n0 = ($b * $inv_ar) % $p;
        if ($n0 < 0) {
            $n0 += $p;
        }

        // Now n ≡ n0 (mod p) and n ≡ r (mod p-1)
        // Solve using CRT
        // n = n0 + k*p
        // n ≡ r (mod p-1)
        // n0 + k*p ≡ r (mod p-1)
        // k*p ≡ (r - n0) (mod p-1)
        // Since p ≡ 1 (mod p-1), this becomes k ≡ (r - n0) (mod p-1)
        // So k = (r - n0) mod (p-1)
        $k = ($r - $n0) % ($p - 1);
        if ($k < 0) {
            $k += $p - 1;
        }

        // The smallest n is n0 + k*p
        $n_start = $n0 + $k * $p;

        // The period is p*(p-1)
        $period = $p * ($p - 1);

        // Count how many n in [1, x] are of the form n_start + t*period
        if ($n_start > $x) {
            continue;
        }

        // Number of terms: floor((x - n_start) / period) + 1
        $count += intdiv($x - $n_start, $period) + 1;
    }

    echo $count . "\n";
}

function pow_mod($base, $exp, $mod) {
    $result = 1;
    $base = $base % $mod;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = ($result * $base) % $mod;
        }
        $exp = intdiv($exp, 2);
        $base = ($base * $base) % $mod;
    }
    return $result;
}

function mod_inverse($a, $m) {
    // Extended Euclidean Algorithm
    $g = gcd_extended($a, $m, $x, $y);
    if ($g != 1) {
        return null; // Inverse doesn't exist
    } else {
        $res = ($x % $m + $m) % $m;
        return $res;
    }
}

function gcd_extended($a, $b, &$x, &$y) {
    if ($a == 0) {
        $x = 0;
        $y = 1;
        return $b;
    }
    $x1 = 0;
    $y1 = 0;
    $g = gcd_extended($b % $a, $a, $x1, $y1);
    $x = $y1 - intdiv($b, $a) * $x1;
    $y = $x1;
    return $g;
